const requirementsData = "data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,";
const evidenceData = "data:application/vnd.openxmlformats-officedocument.wordprocessingml.document;base64,";

// Install once for each browser, preserving existing cases and their numbers.
export function installDigitalAuditCases(existing: ObjectionCase[]): ObjectionCase[] {
  const cases = [...existing];
  for (let n = 1; n <= 9; n++) {
    const name = `Акционерное общество "Digital audit #${n}"`;
    if (cases.some(c => c.org === name && c.appealType === "Жалоба на уведомление" && c.appealNumber === "5-Ж")) continue;
    const c = makeCase({
      id: nextCaseNumber(cases, "Жалоба на уведомление", "2026-09-08"),
      type: "notice", appealType: "Жалоба на уведомление", appealLanguage: "ru", appealNumber: "5-Ж", appealDate: "2026-09-08",
      org: name, orgTranslations: { ru: name }, bin: "001002003004", applicantIdentifierType: "БИН", address: "города Алматы", applicant: "",
      registered: "2026-09-08", filed: "2026-09-08", channel: "Веб-портал государственных закупок", issuer: "ДВГА по г. Алматы", authority: "Апелляционная комиссия при Министерстве финансов РК",
      document: { number: "5-У", date: "2026-09-07", received: "2026-09-08", name: "Уведомление об устранении нарушений", appealExplained: true },
      agendaDetails: { procurementMethod: "конкурс", customerName: "Школа №5", customerBin: "159263478159", auditObjectName: name, auditObjectBin: "001002003004", applicantIsAuditObjectRepresentative: false },
      request: description, amount: 1000005,
      issues: [5, 10].map((point, i) => ({ id: `point${i+1}`, number: String(point), title: `${point} ${issue}`, finding: "", argument: `${point} ${argument}`, evidence: "Тест 2.docx", disputed: true, amount: 0 })),
    });
    c.documents = [
      { name: "ТЕст 01(1).docx", filename: "ТЕст 01(1).docx", kind: "attachment", text: "Требования заявителя", author: "Заявитель", date: "2026-09-08", dataUrl: requirementsData },
      ...[1,2].map(i => ({ name: "Тест 2.docx", filename: "Тест 2.docx", kind: "attachment" as const, text: `Доказательства по оспариваемому пункту ${i}`, author: "Заявитель", date: "2026-09-08", dataUrl: evidenceData })),
    ];
    c.history.push({ date: "2026-09-08", actor: "Заявитель", title: "Добавлены требования заявителя", text: "ТЕст 01(1).docx" });
    cases.push(c);
  }
  return cases;
}
